texts.common/diplomatic_actions/00_relations_a:
increase_relations = {
	groups= {
		general
	}

	requires_approval = no
	show_confirmation_box = no

	selectable = {
		NOT = { is_country_type = decentralized }
	}

	potential = {
		scope:target_country = {
			NOT = { is_country_type = decentralized }
		}
	}

	possible = {
		NOT = { has_diplomatic_pact = { who = scope:target_country type = damage_relations } }
	}

	pact = {
		cost = 150
		is_two_sided_pact = no
		show_in_outliner = yes

		max_target_involvement = 1000
		target_involvement_applies_to = source_country

		relations_progress_per_day = 3 # At 100, +1 relations
		relations_improvement_max = 50

			requirement_to_maintain = {
			trigger = {
				has_diplomatic_relevance = scope:target_country
			}
		}

		requirement_to_maintain = {
			trigger = {
				custom_tooltip = {
					text = "DIPLOMATIC_PACT_REQUIREMENT_AT_PEACE"
					NOT = { has_war_with = scope:target_country }
				}
			}
		}

		requirement_to_maintain = {
			trigger = {
				custom_tooltip = {
					text = "DIPLOMATIC_PACT_REQUIREMENT_NOT_DECENTRALIZED"
					NOT = { is_country_type = decentralized }
					scope:target_country = {
						NOT = { is_country_type = decentralized }
					}
				}
			}
		}

		requirement_to_maintain = {
			trigger = {
				custom_tooltip = {
					text = DIPLO_ACTION_RELATIONS_AMICABLE_OR_GREATER_NOT
					NOT = {
						scope:target_country.relations:root >= relations_threshold:amicable
					}
				}
			}
		}

		requirement_to_maintain = {
			trigger = {
				NOT = { has_diplomats_expelled = scope:target_country }
			}
		}

		requirement_to_maintain = {
			trigger = {
				NOT = { scope:target_country = { has_diplomats_expelled = root } }
			}
		}
	}

	ai = {
		max_influence_spending_fraction = 0.25

		evaluation_chance = {
			value = 0.5
		}

		propose_score = {
			value = 5

			if = {
				limit = {
					OR = {
						ai_has_regional_objective_befriend_reason = { TARGET = scope:target_country }
						ai_is_regional_objective_protect_target = { TARGET = scope:target_country }
					}
				}

				add = 20
			}

			if = {
				limit = {
					has_attitude = {
						who = scope:target_country
						attitude = protective
					}
				}

				add = 5
			}

			if = {
				limit = {
					has_attitude = {
						who = scope:target_country
						attitude = conciliatory
					}
				}

				add = 20
			}

			if = {
				limit = {
					has_journal_entry = je_hawaiian_interest
					c:HAW ?= {
						this = scope:target_country
					}
				}
				add = 20
			}

			add = {
				value = scope:target_country.country_rank
				multiply = 3
			}

			if = {
				limit = {
					OR = {
						is_subject_of = scope:target_country
						scope:target_country = { is_subject_of = root }
					}
				}

				multiply = 2
			}
		}

		will_propose = {
			OR = {
				AND = {
					has_attitude = {
						who = scope:target_country
						attitude = cooperative
					}
					country_rank <= scope:target_country.country_rank
				}
				has_attitude = {
					who = scope:target_country
					attitude = conciliatory
				}
				has_attitude = {
					who = scope:target_country
					attitude = genial
				}
				has_attitude = {
					who = scope:target_country
					attitude = protective
				}
				ai_has_regional_objective_befriend_reason = { TARGET = scope:target_country }
				ai_is_regional_objective_protect_target = { TARGET = scope:target_country }
			}
		}

		will_break = {
			NOR = {
				ai_has_regional_objective_befriend_reason = { TARGET = scope:target_country }
				ai_is_regional_objective_protect_target = { TARGET = scope:target_country }
			}

			OR = {
				NOR = {
					has_attitude = {
						who = scope:target_country
						attitude = genial
					}
					has_attitude = {
						who = scope:target_country
						attitude = conciliatory
					}
					has_attitude = {
						who = scope:target_country
						attitude = cooperative
					}
					has_attitude = {
						who = scope:target_country
						attitude = protective
					}
				}
				AND = {
					scope:target_country.relations:root >= relations_threshold:amicable
					OR = {
						country_rank >= rank_value:minor_power
						NOT = {
							has_attitude = {
								who = scope:target_country
								attitude = genial
							}
						}
					}
				}
			}

		}
	}
}

damage_relations = {
	groups= {
		general
	}

	requires_approval = no
	show_confirmation_box = no

	selectable = {
		NOT = { is_country_type = decentralized }
	}

	potential = {
		scope:target_country = {
			NOT = { is_country_type = decentralized }
		}
	}

	possible = {
		NOT = { has_diplomatic_pact = { who = scope:target_country type = increase_relations } }
	}

	pact = {
		cost = 100
		is_hostile = yes
		is_two_sided_pact = no
		infamy_affects_maintenance = no
		show_in_outliner = yes

		relations_progress_per_day = -3 # At -100, -1 relations
		relations_improvement_min = -50

		requirement_to_maintain = {
			trigger = {
				has_diplomatic_relevance = scope:target_country
			}
		}

		requirement_to_maintain = {
			trigger = {
				custom_tooltip = {
					text = DIPLO_ACTION_RELATIONS_COLD_OR_LESS_NOT
					scope:target_country.relations:root > relations_threshold:cold
				}
			}
		}

		requirement_to_maintain = {
			trigger = {
				custom_tooltip = {
					text = "DIPLOMATIC_PACT_REQUIREMENT_NOT_DECENTRALIZED"
					NOT = { is_country_type = decentralized }
					scope:target_country = {
						NOT = { is_country_type = decentralized }
					}
				}
			}
		}
	}

	ai = {
		max_influence_spending_fraction = 0.15

		evaluation_chance = {
			value = 0.5
		}

		propose_score = {
			value = 10

			if = {
				limit = {
					OR = {
						has_attitude = {
							who = scope:target_country
							attitude = belligerent
						}
						has_attitude = {
							who = scope:target_country
							attitude = domineering
						}
						has_attitude = {
							who = scope:target_country
							attitude = rebellious
						}
					}
				}

				add = 10
			}

			if = {
				limit = {
					OR = {
						is_subject_of = scope:target_country
						scope:target_country = { is_subject_of = root }
					}
				}

				multiply = 5
			}

			if = {
				limit = {
					AND = {
						has_radical_leftist_government = no
						scope:target_country = {
							has_radical_leftist_government = yes
						}
					}
				}
				multiply = 2
			}

			if = {
				limit = {
					AND = {
						has_radical_leftist_economy = no
						scope:target_country = {
							has_radical_leftist_economy = yes
						}
					}

				}
				multiply = 2
			}
		}

		will_propose = {
			OR = {
				AND = {
					has_attitude = {
						who = scope:target_country
						attitude = antagonistic
					}
					scope:target_country.relations:root > 0
				}
				has_attitude = {
					who = scope:target_country
					attitude = belligerent
				}
				has_attitude = {
					who = scope:target_country
					attitude = domineering
				}
				has_attitude = {
					who = scope:target_country
					attitude = rebellious
				}
			}
			scope:target_country.relations:root > relations_threshold:poor
		}

		will_break = {
			OR = {
				NOR = {
					has_attitude = {
						who = scope:target_country
						attitude = belligerent
					}
					has_attitude = {
						who = scope:target_country
						attitude = domineering
					}
					has_attitude = {
						who = scope:target_country
						attitude = antagonistic
					}
					has_attitude = {
						who = scope:target_country
						attitude = rebellious
					}
				}
				scope:target_country.relations:root <= relations_threshold:poor
			}
		}
	}
}

texts.common/diplomatic_actions/03_violate_sov:
violate_sovereignty = {
	groups= {
		general
	}
	requires_approval = yes
	should_notify_third_parties = yes
	violates_sovereignty = yes
	can_use_obligations = yes

	selectable = {
		NOT = { is_country_type = decentralized }
	}

	potential = {
		is_at_war = yes

		scope:target_country = {
			NOT = {
				is_country_type = decentralized
				is_subject_of = ROOT
			}
		}
		NOT = {
			has_war_with = scope:target_country
			is_in_war_together = scope:target_country
		}
	}

	possible = {
		scope:target_country.relations:root < relations_threshold:amicable

		is_revolutionary = no

		scope:target_country = {
			is_revolutionary = no
		}

		# this localization only makes sense if you are already at war
		trigger_if = {
			limit = {
				is_at_war = yes
			}
			custom_tooltip = {
				text = "violate_sovereignty_trigger_not"
				any_scope_war = {
					is_warleader = root
					violate_sovereignty_war_check = yes
				}
			}
		}
	}

	accept_effect = {
		create_incident = {
			value = 15
			country = scope:target_country
		}

		scope:target_country = {
			violate_sovereignty_join = {
				violator = root
				target = scope:target_country
				join_violator = yes
			}
		}
	}

	decline_effect = {
		save_scope_as = initiator

		create_incident = {
			value = 10
			country = scope:target_country
		}

		scope:target_country = {
			violate_sovereignty_join = {
				violator = root
				target = scope:target_country
				join_violator = no
			}
		}

		# could potentially be several wars but only show one in situation for now
		random_scope_violate_sovereignty_wars = {
			save_scope_as = war
		}

		# send situation to all relevant countries asking them to help scope:target_country out
		every_scope_violate_sovereignty_interested_parties = {
			trigger_event = { id = diplomatic_events.1 days = 0 }
		}
	}

	ai = {
		evaluation_chance = {
			value = 0

			if = {
				limit = {
					is_at_war = yes
					any_scope_war = {
						is_warleader = root
					}
				}
				add = 1
			}
		}

		propose_score = {
			value = 100
		}

		accept_score = {
			value = 0

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_BASE"
				value = -100
			}

			if = {
				limit = {
					has_strategy = ai_strategy_armed_isolationism
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ISOLATIONIST"
					add = -25
				}
			}

			if = {
				limit = {
					"scope:actor.ai_army_comparison(root)" > 0
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ARMY_STRENGTH"
					value = "scope:actor.ai_army_comparison(root)"
					multiply = 2
					max = 50
				}
			}
			else = {
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_ARMY_STRENGTH"
					value = -1000
				}
			}

			if = {
				limit = {
					"scope:actor.ai_ideological_opinion(root)" > 0
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_IDEOLOGICAL_OPINION"
					value = "scope:actor.ai_ideological_opinion(root)"
					multiply = 0.5
					max = 20
				}
			}
			else_if = {
				limit = {
					"scope:actor.ai_ideological_opinion(root)" < 0
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_IDEOLOGICAL_OPINION_NEGATIVE"
					value = "scope:actor.ai_ideological_opinion(root)"
					multiply = 1
					min = -40
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_ATTITUDE"
				if = {
					limit = {
						OR = {
							has_attitude = {
								who = scope:actor
								attitude = genial
							}
							has_attitude = {
								who = scope:actor
								attitude = conciliatory
							}
							has_attitude = {
								who = scope:actor
								attitude = loyal
							}
							has_attitude = {
								who = scope:actor
								attitude = cooperative
							}
						}
					}
					value = 15
				}
				if = {
					limit = {
						has_attitude = {
							who = scope:actor
							attitude = cautious
						}
					}
					value = -25
				}
				if = {
					limit = {
						OR = {
							has_attitude = {
								who = scope:actor
								attitude = antagonistic
							}
							has_attitude = {
								who = scope:actor
								attitude = domineering
							}
							has_attitude = {
								who = scope:actor
								attitude = belligerent
							}
							has_attitude = {
								who = scope:actor
								attitude = rebellious
							}
							has_attitude = {
								who = scope:actor
								attitude = protective
							}
						}
					}
					value = -50
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_RELATIONS"
				if = {
					limit = {
						"relations(scope:actor)" < relations_threshold:cordial
					}
					value = -25
				}
				if = {
					limit = {
						"relations(scope:actor)" >= relations_threshold:cordial
						"relations(scope:actor)" < relations_threshold:amicable
					}
					value = 10
				}
				if = {
					limit = {
						"relations(scope:actor)" >= relations_threshold:amicable
						"relations(scope:actor)" < relations_threshold:friendly
					}
					value = 25
				}
				if = {
					limit = {
						"relations(scope:actor)" >= relations_threshold:friendly
					}
					value = 50
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_INFAMY"
				if = {
					limit = {
						"scope:actor.infamy" >= infamy_threshold:infamous
						"scope:actor.infamy" < infamy_threshold:notorious
					}
					value = -10
				}
				if = {
					limit = {
						"scope:actor.infamy" >= infamy_threshold:notorious
						"scope:actor.infamy" < infamy_threshold:pariah
					}
					value = -25
				}
				if = {
					limit = {
						"scope:actor.infamy" >= infamy_threshold:pariah
					}
					value = -50
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_RANK"

				if = {
					limit = { scope:actor = { country_rank > root.country_rank } }
					value = 20
				}

				if = {
					limit = { scope:actor = { country_rank < root.country_rank } }
					value = -20
				}
			}

			if = {
				limit = {
					has_powerful_protectors = {
						ACTOR_SCOPE = scope:actor
					}
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_POWERFUL_PROTECTORS_THEM"
					value = -50
				}
			}
		}
	}
}

texts.common/diplomatic_actions/26_join_power_:
join_power_bloc = {
	requires_approval = yes
	can_use_obligations = yes
	should_notify_third_parties = yes
	groups = { general }
	confirmation_sound = "event:/SFX/UI/MapInteraction/SubjectInteractions/power_bloc_join_request"

	selectable = {
		NOT = { is_country_type = decentralized }
		is_revolutionary = no
		is_subject = no
	}

	potential = {
		scope:target_country = {
			is_power_bloc_leader = yes
		}
	}

	possible = {
		# Must not be able to immediately start a power struggle
		custom_tooltip = {
			text = "NO_POWER_STRUGGLE_BLOC_JOIN"
			OR = {
				prestige < scope:target_country.prestige
				country_rank < scope:target_country.country_rank
			}
		}

		scope:target_country.power_bloc ?= {
			leverage_advantage = {
				target = root
				value >= leverage_threshold_to_invite
			}

			NOT = {
				any_power_bloc_member = {
					is_diplomatic_play_enemy_of = root
				}
			}
		}
	}

	accept_effect = {
		join_power_bloc = scope:target_country
	}

	decline_effect = {
		change_relations = { country = scope:target_country value = -20 }

		# Remove the entire leverage advantage if they say no
		scope:target_country.power_bloc ?= {
			add_leverage = {
				target = scope:actor
				value = {
					value = "leverage_advantage(scope:actor)"
					multiply = -1
				}
			}
		}
	}

	ai = {
		evaluation_chance = {
			value = 0.01 # AI shouldn't volunteer into power blocs all that often
		}

		accept_score = {
			value = 0

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_BASE"
				value = -100
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_LEVERAGE_OF_TARGET"
				value = "power_bloc.leverage_advantage(scope:actor)"
				multiply = 0.5
				min = 0
				max = 200
			}

			### Impact on Cohesion
			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_DECREASED_COHESION"
				value = "power_bloc.predicted_cohesion_percentage_with(scope:actor)"
				subtract = "power_bloc.current_cohesion_number"
				multiply = 2 # -2 acceptance for each lost point of cohesion

				if = {
					limit = { "power_bloc.current_cohesion_number" <= 20 }
					multiply = 5
				}
				else_if = {
					limit = { "power_bloc.current_cohesion_number" <= 40 }
					multiply = 2
				}

				max = 0
			}

			### How we fit their selected identity
			add = ai_accept_join_request_score

			# Ideological opinion is always a factor, but much weaker for non ideological unions
			# Score for ideological unions is handled in ai_accept_join_request_score script value
			if = {
				limit = {
					scope:target_country.power_bloc ?= {
						NOT = { has_identity = identity:identity_ideological_union }
					}
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_IDEOLOGICAL_OPINION"
					value = "scope:actor.ai_ideological_opinion(root)"
					multiply = 0.25
					max = 25
					min = -25
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_ATTITUDE"
				if = {
					limit = {
						OR = {
							has_attitude = {
								who = scope:actor
								attitude = genial
							}
							has_attitude = {
								who = scope:actor
								attitude = protective
							}
						}
					}
					value = 100
				}
				else_if = {
					limit = {
						OR = {
							has_attitude = {
								who = scope:actor
								attitude = cooperative
							}
							has_attitude = {
								who = scope:actor
								attitude = conciliatory
							}
						}
					}
					value = 50
				}
				else_if = {
					limit = {
						has_attitude = {
							who = scope:actor
							attitude = domineering
						}
					}
					value = 25
				}
				else_if = {
					limit = {
						OR = {
							has_attitude = {
								who = scope:actor
								attitude = antagonistic
							}
							has_attitude = {
								who = scope:actor
								attitude = belligerent
							}
						}
					}
					value = -100
				}
				else = {
					value = -25
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_RELATIONS"
				if = {
					limit = {
						"relations(scope:actor)" < relations_threshold:friendly
					}
					value = 0
				}
				if = {
					limit = {
						"relations(scope:actor)" >= relations_threshold:amicable
						"relations(scope:actor)" < relations_threshold:friendly
					}
					value = 50
				}
				if = {
					limit = {
						"relations(scope:actor)" >= relations_threshold:friendly
					}
					value = 100
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_INFAMY"
				if = {
					limit = {
						"scope:actor.infamy" >= infamy_threshold:infamous
						"scope:actor.infamy" < infamy_threshold:notorious
					}
					value = -5
				}
				if = {
					limit = {
						"scope:actor.infamy" >= infamy_threshold:notorious
						"scope:actor.infamy" < infamy_threshold:pariah
					}
					value = -10
				}
				if = {
					limit = {
						"scope:actor.infamy" >= infamy_threshold:pariah
					}
					value = -25
				}
			}

			if = {
				limit = {
					scope:actor = {
						has_variable = pro_lobby_proposal_power_bloc
						var:pro_lobby_opportunity_target ?= scope:target_country
					}
				}
				add = {
					desc = "LOBBY_OPPORTUNITY_BONUS"
					value = 100
				}
			}

			if = {
				limit = {
					scope:actor = {
						has_variable = anti_lobby_proposal_power_bloc
