da_increase_autonomy_of_self = {
	groups = {
		subject
	}
	requires_approval = yes
	show_effect_in_tooltip = yes
	can_use_obligations = yes
	uses_random_approval = yes

	texture = "gfx/interface/icons/diplomatic_action_icons/da_increase_autonomy.dds"

	potential = {
		is_subject = yes
		can_increase_autonomy = yes
	}

	possible = {
		scope:target_country = {
			NOT = {
				is_diplomatic_play_enemy_of = root
			}
		}
		liberty_desire >= 75
		can_increase_autonomy = yes

		OR = {
			NOT = {
				has_government_type = gov_chartered_company
			}
			has_technology_researched = civilizing_mission
		}

		OR = {
			NOT = {
				is_subject_type = subject_type_personal_union
			}
			has_technology_researched = nationalism
		}

		custom_tooltip = {
			text = "REQUEST_AUTONOMY_ON_COOLDOWN"
			NOT = {
				scope:target_country = {
					any_diplomatic_catalyst = {
						is_diplomatic_catalyst_type = catalyst_autonomy_increase_requested
						target = root
					}
				}
			}
		}
		custom_tooltip = {
			text = "CHANGE_AUTONOMY_ON_COOLDOWN_SUBJECT"
			NOT = {
				scope:target_country = {
					any_diplomatic_catalyst = {
						is_diplomatic_catalyst_type = catalyst_autonomy_change_imposed
						target = scope:target_country
					}
				}
			}
		}
	}

	accept_effect = {
		increase_autonomy = yes
		add_liberty_desire = -30
		create_bidirectional_truce = { country = scope:target_country months = 60 }
		scope:target_country = { change_relations = { country = root value = -20 } }
		hidden_effect = {
			scope:target_country = {
				create_diplomatic_catalyst = {
					type = catalyst_autonomy_increase_requested
					target = root
				}
			}
			create_diplomatic_catalyst = {
				type = catalyst_autonomy_change_imposed
				target = scope:target_country
			}
		}
	}

	decline_effect = {
		add_liberty_desire = 10
		scope:target_country = { change_relations = { country = root value = -30 } }
		hidden_effect = {
			scope:target_country = {
				create_diplomatic_catalyst = {
					type = catalyst_autonomy_increase_requested
					target = root
				}
			}
			create_diplomatic_catalyst = {
				type = catalyst_autonomy_increase_denied
				target = scope:target_country
			}
		}
	}

	ai = {
		evaluation_chance = {
			value = 0.25
		}

		accept_score = {
			value = 0

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_BASE"
				value = -100
			}

			if = {
				limit = {
					"scope:actor.ai_ideological_opinion(root)" > 0
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_IDEOLOGICAL_OPINION"
					value = "scope:actor.ai_ideological_opinion(root)"
					multiply = 0.5
					max = 25
				}
			}
			else_if = {
				limit = {
					"scope:actor.ai_ideological_opinion(root)" < 0
				}
				add = {
					desc = "DIPLOMATIC_ACCEPTANCE_IDEOLOGICAL_OPINION_NEGATIVE"
					value = "scope:actor.ai_ideological_opinion(root)"
					multiply = 0.5
					min = -25
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_ATTITUDE"
				if = {
					limit = {
						has_attitude = {
							who = scope:actor
							attitude = protective
						}
					}
					value = 50
				}
				else_if = {
					limit = {
						has_attitude = {
							who = scope:actor
							attitude = domineering
						}
					}
					value = -50
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_CHANCE_TO_WIN_DIPLOMATIC_PLAY"
				value = "scope:actor.potential_diplomatic_play_power_ratio(root)"
				subtract = 0.5
				multiply = 50
				max = 100
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_ACTOR_LIBERTY_DESIRE"
				value = "scope:actor.liberty_desire"
				subtract = 75
				multiply = 2
				min = -50
				max = 50
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_RELATIONS"
				if = {
					limit = {
						"relations(scope:actor)" >= relations_threshold:friendly
					}
					value = 50
				}
				else_if = {
					limit = {
						"relations(scope:actor)" >= relations_threshold:amicable
					}
					value = 25
				}
				else_if = {
					limit = {
						"relations(scope:actor)" >=  relations_threshold:cordial
					}
					value = 10
				}
				else_if = {
					limit = {
						"relations(scope:actor)" > relations_threshold:poor
					}
					value = -25
				}
				else = {
					value = -50
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_INFAMY"
				if = {
					limit = {
						"scope:actor.infamy" >= infamy_threshold:infamous
						"scope:actor.infamy" < infamy_threshold:notorious
					}
					value = -10
				}
				if = {
					limit = {
						"scope:actor.infamy" >= infamy_threshold:notorious
						"scope:actor.infamy" < infamy_threshold:pariah
					}
					value = -25
				}
				if = {
					limit = {
						"scope:actor.infamy" >= infamy_threshold:pariah
					}
					value = -50
				}
			}

			add = {
				desc = "je_peru_bolivia"

				if = {
					limit = {
						is_involved_in_journal_entry = je_peru_bolivia
						scope:target_country = {
							c:BOL ?= this
							is_involved_in_journal_entry = je_peru_bolivia
						}
					}
					add = -300
				}
			}

			add = {
				desc = "DIPLOMATIC_ACCEPTANCE_RUSSIA_NO_APPEASEMENT_POLAND"

				if = {
					limit = {
						ai_russia_refuses_polish_autonomy = yes
					}
					add = -300
				}
			}
		}

		propose_score = {
			value = 100

			if = { # Hungary should want independence
				limit = {
					has_journal_entry = je_hungarian_revolution
					OR = {
						has_variable = hungarian_revolution_twelve_points_var
						has_variable = hungarian_revolution_annex_transylvania_button_var
						AND = {
							is_involved_in_journal_entry = je_springtime_of_the_peoples
							has_variable = had_springtime_revolution
						}
					}
					scope:target_country = {
						has_journal_entry = je_matter_of_hungary
					}
				}
				multiply = 3
			}
		}

		will_propose = {
			OR = {
				has_strategy = ai_strategy_subject_strengthen_self
				has_strategy = ai_strategy_subject_break_free
			}
		}

		will_propose_even_if_not_accepted = {
			always = yes
		}
	}
}

