					}
				}
			}
		}
		OR = {
			is_subject = no
			aggressive_diplomatic_plays_permitted = yes
		}
    }

    accept_effect = {
        custom_tooltip = support_separatism_action_effect_breakdown
    }

    is_hostile = yes

    pact = {
        cost = 100
        is_hostile = yes
        is_two_sided_pact = no
        show_in_outliner = yes

		max_target_involvement = 1000
		target_involvement_applies_to = source_country

		relations_progress_per_day = -1 # At -100, -1 relations
		relations_improvement_min = -25

		requirement_to_maintain = {
			trigger = {
				has_diplomatic_relevance = scope:target_country
			}
		}

		requirement_to_maintain = {
			trigger = {
				custom_tooltip = {
					text = "DIPLOMATIC_PACT_REQUIREMENT_AT_PEACE"
					NOT = { has_war_with = scope:target_country }
				}
			}
		}

		requirement_to_maintain = {
			trigger = {
				custom_tooltip = {
					text = "DIPLOMATIC_PACT_REQUIREMENT_NOT_DECENTRALIZED"
					NOT = { is_country_type = decentralized }
					scope:target_country = {
						NOT = { is_country_type = decentralized }
					}
				}
			}
		}

		requirement_to_maintain = {
			trigger = {
				custom_tooltip = {
					text = DIPLO_ACTION_RELATIONS_AMICABLE_OR_GREATER_NOT
					NOT = {
						scope:target_country.relations:root >= relations_threshold:amicable
					}
				}
			}
		}

		requirement_to_maintain = {
			trigger = {
					scope:target_country = {
						any_primary_culture = {
							NOT = { is_primary_culture_of = root }
						}
					}
			}
		}

		requirement_to_maintain = {
			trigger = {
				NOT = { scope:target_country = { has_diplomats_expelled = root } }
			}
		}
    }

    ai = {
		max_influence_spending_fraction = 0.25

        evaluation_chance = {
            value = 0

			if = {
				limit = {
					any_primary_culture = {
						culture_has_national_awakening = yes
					}
				}
				add = 0.25
			}

			if = {
				limit = {
					OR = {
						has_journal_entry = je_balkan_national_awakenings
						has_journal_entry = je_risorgimento
						has_journal_entry = je_christ_of_nations
					}
				}
				add = 0.75
			}
        }

		propose_score = {
			value = 10

			if = {
				limit = {
					OR = {
						has_attitude = {
							who = scope:target_country
							attitude = belligerent
						}
						has_attitude = {
							who = scope:target_country
							attitude = domineering
						}
						has_attitude = {
							who = scope:target_country
							attitude = antagonistic
						}
						has_attitude = {
							who = scope:target_country
							attitude = defiant
						}
						has_attitude = {
							who = scope:target_country
							attitude = rebellious
						}
					}
				}

				add = 10
			}

			if = {
				limit = {
					is_subject_of = scope:target_country
				}
				multiply = 2.5
			}

			if = {
				limit = {
					AND = {
						has_radical_leftist_government = no
						scope:target_country = {
							has_radical_leftist_government = yes
						}
					}

				}
				multiply = 2.5
			}

			if = {
				limit = {
					AND = {
						has_radical_leftist_economy = no
						scope:target_country = {
							has_radical_leftist_economy = yes
						}
					}

				}
				multiply = 2.5
			}
		}

		will_propose = {
			OR = {
				AND = {
					has_attitude = {
						who = scope:target_country
						attitude = antagonistic
					}
					scope:target_country.relations:root <= relations_threshold:poor
				}
				has_attitude = {
					who = scope:target_country
					attitude = belligerent
				}
				has_attitude = {
					who = scope:target_country
					attitude = domineering
				}
				has_attitude = {
					who = scope:target_country
					attitude = defiant
				}
				has_attitude = {
					who = scope:target_country
					attitude = rebellious
				}
			}
		}

		will_break = {
			NOR = {
				has_attitude = {
					who = scope:target_country
					attitude = belligerent
				}
				has_attitude = {
					who = scope:target_country
					attitude = domineering
				}
				has_attitude = {
					who = scope:target_country
					attitude = defiant
				}
				has_attitude = {
					who = scope:target_country
					attitude = antagonistic
				}
				has_attitude = {
					who = scope:target_country
					attitude = rebellious
				}
			}
		}
    }
}

