		#Montenegro events
		if = {
			limit = {
				c:MON ?= THIS
			}
			on_law_enactment_started_montenegro_effect = yes
		}
		#Abolishing Monarchy
		if = {
			limit = {
				has_law = law_type:law_monarchy
				OR = {
					is_enacting_law = law_type:law_corporate_state
					is_enacting_law = law_type:law_presidential_republic
					is_enacting_law = law_type:law_parliamentary_republic
					is_enacting_law = law_type:law_council_republic
					is_enacting_law = law_type:law_corporate_state
				}
			}
			country_launch_abolish_monarchy_effect = yes # launch je_abolish_monarchy
		}
		# Negotiation achievement
		if = {
			limit = {
				any_interest_group = {
					law_enactment_stance = {
						law = owner.currently_enacting_law.type
						value < neutral
					}
					ig_counts_as_marginal = no
					count >= 2
				}
			}
			set_variable = unanimity_achievement_possible
		}
	}
}

