# scope:target = Uprising country
on_revolution_start = {
	effect = {
		### Movement type variable setting
		on_revolution_start_set_civil_war_variables_effect = yes
		on_revolution_start_handle_target_revolution_effect = yes
		if = {
			limit = {
				has_journal_entry = je_warlord_china
				NOT = { has_variable = china_warlord_explosion_revolution }
			}
			chi_remove_1_fragile_unity = yes
			set_variable = china_warlord_explosion_revolution
		}
		if = {
			limit = {
				is_involved_in_journal_entry = je_paris_commune
			}
			on_revolution_start_paris_commune_effect = yes
		}
		if = {
			limit = {
				has_dlc_feature = voice_of_the_people_content
				c:KRA ?= root
				c:AUS ?= {
					any_subject_or_below = {
						c:KRA ?= this
					}
				}
			}
			c:AUS ?= {
				trigger_event = { id = krakow.1 days = 3 popup = yes }
			}
		}
		if = {
			limit = {
				has_dlc_feature = voice_of_the_people_content
				c:FRA ?= ROOT
			}
			on_revolution_start_french_monarchist_restoration_effect = yes
		}
		if = {
			limit = {
				has_dlc_feature = ep1_content
				c:KOR ?= {
					this = ROOT
					is_subject = yes
					overlord ?= {
						OR = {
							country_has_primary_culture = cu:han
							country_has_primary_culture = cu:manchu
						}
						has_technology_researched = electric_telegraph
					}
				}
				c:JAP ?= {
					NOT = {
						has_law_or_variant = law_type:law_isolationism
					}
					has_interest_marker_in_region = sr:region_northeast_asia
					has_technology_researched = electric_telegraph
				}
			}
			on_revolution_start_korean_rebellion_effect = yes
		}
		if = { # Script hack for Indian revolutions
			limit = {
				c:BIC ?= ROOT
				ROOT = {
					any_civil_war = {
						is_civil_war_type = revolution
						political_movement ?= {
							NOR = {
								is_political_movement_type = movement_religious_majority
								is_political_movement_type = movement_cultural_majority
								is_political_movement_type = movement_utilitarian
								culture ?= {
									has_discrimination_trait_group = heritage_group_european
								}
							}
						}
					}
				}
			}
			on_revolution_start_indian_revolution_effect = yes
		}
		### Carlists and Miguelists
		if = {
			limit = {
				scope:target ?= {
					is_secessionist = no
					has_law = law_type:law_monarchy
					OR = {
						var:civil_war_type_var ?= movement_type:movement_carlist
						var:civil_war_type_var ?= movement_type:movement_miguelist
					}
				}
			}
			on_revolution_start_carlist_miguelist_ruler_effect = yes
		}
		# Meiji civil wars
		if = {
			limit = {
				country_has_pending_meiji_restoration = yes
			}
			meiji_civil_war_effects = yes
		}
		if = {
			limit = {
				NOT = { has_global_variable_map = first_proletarian_revolution }
				scope:target ?= {
					has_law_or_variant = law_type:law_factory_councils
				}
			}
			add_to_global_variable_map = { name = first_proletarian_revolution key = scope:target.capital.state_region value = year }
		}
		if = {
			limit = {
				scope:target ?= {
					var:civil_war_type_var ?= movement_type:movement_labor
					OR = {
						coa_republic_trigger = no
						has_law_or_variant = law_type:law_corporate_state
					}
				}
			}
			on_revolution_start_revolutionary_republic_effect = yes
		}
		if = {
			limit = {
				country_has_monarchy_law = yes
				scope:target ?= {
					country_has_monarchy_law = no
				}
			}
			set_variable = anti_monarchist_revolution
		}
		set_variable = { name = recent_coup_or_revolution_var value = 0 }
	}
}

